<script lang="ts">import {page} from '$app/state';import {goto} from '$app/navigation';import {session} from '$lib/stores/session';import {auth} from '$lib/api';let open=$state(false);let current=$state(page.url.pathname);let publicLinks=[['Home','/','fa-house'],['Marketplace','/marketplace','fa-store'],['Login','/auth/login','fa-right-to-bracket'],['Register','/auth/register','fa-user-plus']];let farmerLinks=[['Dashboard','/dashboard','fa-chart-line'],['Marketplace','/marketplace','fa-store'],['Wallet','/wallet','fa-wallet'],['Create listing','/dashboard/listings/new','fa-plus'],['Settings','/settings','fa-gear']];let producerLinks=[['Dashboard','/dashboard','fa-chart-line'],['My listings','/dashboard/listings/new','fa-list'],['Wallet','/wallet','fa-wallet'],['Settings','/settings','fa-gear']];$effect(()=>{current=page.url.pathname});function logout(){auth.logout?.();session.set(null);open=false;goto('/')}</script><button class="menu-trigger" aria-label="Open navigation" aria-expanded={open} onclick={()=>open=!open}><i class="fa-solid fa-bars"></i></button>{#if open}<div class="nav-pop"><div class="brand">REGEN<span>FEED</span></div>{#each ($session?($session?.role==='producer'?producerLinks:farmerLinks):publicLinks) as l}<a class:active={current===l[1]} href={l[1]} onclick={()=>open=false}><span><i class="fa-solid {l[2]}"></i> {l[0]}</span><i class="fa-solid fa-arrow-up-right-from-square"></i></a>{/each}{#if $session}<button class="nav-logout" onclick={logout}><i class="fa-solid fa-right-from-bracket"></i> Log out</button>{/if}<small>Market access for a circular Kenya.</small></div>{/if}